#pragma once#include "H_Class.h"#include <_alarmentry.h>#include <ConnectH.h>template<class T>bool PV_Test( double PV, LPCSTR PointName, int Alarm, int HL, T* pInfo, int sizeinfo, double scaleHi, double scaleLo, double time ){  CAlarmInfo *pAlm = (CAlarmInfo*)pInfo;  if ( (!_finite( pAlm->TP ) || IsNaN(pAlm->TP)) && pAlm ->FL != 0 )  {    pAlm ->FL = 0;    pAlm->memtime = 0;    if ( pAlarm )      (*pAlarm) ( PointName, Alarm, pAlm->PR, false, PV, &pAlm->TM, 0, NULL );    return true;  }  double Scale = scaleHi - scaleLo;  if ( HL > 0 )  {    // H, HH    if ( PV > pAlm->TP )    {      if ( pAlm->memtime < pAlm->TM )        pAlm->memtime += time;      else      {        if ( pAlarm && pAlm ->FL == 0 )          (*pAlarm) ( PointName, Alarm, pAlm->PR, true, PV, &pAlm->TM, 0, NULL );        pAlm ->FL = 1;        return false;      }    }    if ( pAlm ->FL == 0 )      return true;    double DB;    if ( pAlm->DBU == 0 )      DB = pAlm->DB * Scale * 0.01;    else      DB = pAlm->DB;    if ( PV < pAlm->TP - DB )    {      pAlm->memtime = 0;      if ( pAlarm )        (*pAlarm) ( PointName, Alarm, pAlm->PR, false, PV, &pAlm->TM, 0, NULL );      pAlm ->FL = 0;      return true;    }    return false;  }  // L, LL  if ( PV < pAlm->TP )  {    if ( pAlm->memtime < pAlm->TM )      pAlm->memtime += time;    else    {      if ( pAlarm && pAlm ->FL == 0 )        (*pAlarm) ( PointName, Alarm, pAlm->PR, true, PV, &pAlm->TM, 0, NULL );      pAlm ->FL = 1;      return false;    }  }  if ( pAlm ->FL == 0 )    return true;  double DB;  if ( pAlm->DBU == 0 )    DB = pAlm->DB * Scale * 0.01;  else    DB = pAlm->DB;  if ( PV > pAlm->TP + DB )  {    pAlm->memtime = 0;    if ( pAlarm )      (*pAlarm) ( PointName, Alarm, pAlm->PR, false, PV, &pAlm->TM, 0, NULL );    pAlm ->FL = 0;    return true;  }  return false;}